@if(
    not(empty(trim(pipeline().parameters.p_incr_from_val))),
    trim(pipeline().parameters.p_incr_from_val),
    formatDateTime(
        addDays(
            convertTimeZone(utcnow(), 'UTC', 'Korea Standard Time'),
            sub(
                0,
                int(
                    if(
                        empty(trim(pipeline().parameters.p_incr_days)),
                        variables('pv_condition_interval'),
                        trim(pipeline().parameters.p_incr_days)
                    )
                )
            )
        ),
        'yyyy-MM-dd'
    )
)

@if(
    not(empty(trim(pipeline().parameters.p_incr_from_val))),
    trim(pipeline().parameters.p_incr_from_val),
    formatDateTime(
        addToTime(
            convertTimeZone(
                if(
                    empty(trim(pipeline().parameters.p_scheduled_time)),
                    utcnow(),
                    trim(pipeline().parameters.p_scheduled_time)
                ),
                'UTC',
                'Korea Standard Time'
            ),
            sub(
                0,
                if(
                    empty(trim(pipeline().parameters.p_incr_minutes)),
                    int(variables('pv_condition_interval')),
                    int(trim(pipeline().parameters.p_incr_minutes))
                )
            ),
            if(
                empty(trim(pipeline().parameters.p_incr_minutes)),
                if(
                    equals(variables('pv_condition_unit'), 'HOUR'),
                    'Hour',
                    'Minute'
                ),
                'Minute'
            )
        ),
        'yyyy-MM-dd HH:mm:ss'
    )
)

@if(
    not(empty(trim(pipeline().parameters.p_incr_from_val))),
    if(
        equals(length(trim(pipeline().parameters.p_incr_from_val)), 6),
        concat(trim(pipeline().parameters.p_incr_from_val), '01'),
        if(
            equals(length(trim(pipeline().parameters.p_incr_from_val)), 7),
            concat(trim(pipeline().parameters.p_incr_from_val), '-01'),
            trim(pipeline().parameters.p_incr_from_val)
        )
    ),
    startOfMonth(
        addToTime(
            convertTimeZone(utcnow(), 'UTC', 'Korea Standard Time'),
            sub(
                0,
                int(
                    if(
                        empty(trim(pipeline().parameters.p_incr_months)),
                        variables('pv_condition_interval'),
                        trim(pipeline().parameters.p_incr_months)
                    )
                )
            ),
            'Month'
        ),
        'yyyy-MM-dd'
    )
)
